/// <reference path="../pb_data/types.d.ts" />
/* KsuNiMeet — хуки PocketBase.
 *
 * В Supabase эту работу делали триггеры и pg_cron. Здесь то же самое — хуками,
 * то есть кодом в репозитории, а не настройками в чужой панели.
 *
 * Здесь три вещи, которые клиент не должен и не может делать сам:
 *
 *   1. НОМЕР. 8-значный «номер KsuNiMeet» выдаёт сервер. Если бы его выбирал
 *      браузер, любой мог бы занять чужой номер и притвориться им. Клиент
 *      вообще не присылает `phone` — поле заполняется здесь.
 *   2. chat_key и seq. Ключ пары собирается по возрастанию id (у пары ровно
 *      один канал, независимо от того, кто написал первым), а `seq` — это
 *      число, растущее со временем, потому что приложение ждёт от `messages.id`
 *      именно числа (в Supabase это был autoincrement).
 *   3. УБОРКА. Комнаты, фильмы, пинги и присутствие иначе копятся вечно.
 *
 * ПОЧЕМУ require() ВНУТРИ КАЖДОГО ОБРАБОТЧИКА, А НЕ ОДИН РАЗ СВЕРХУ.
 * Обработчики выполняются в пуле заранее прогретых JS-движков. Область
 * видимости обработчика — не файл: ни функции, объявленные в этом файле, ни
 * даже `const`, объявленный сверху, ему не видны. Оба варианта проверены
 * запуском и падают одинаково:
 *      const lib = require(...)     сверху файла  ->  ReferenceError: lib is not defined
 *      function helper() {}         сверху файла  ->  ReferenceError: helper is not defined
 * а клиент вместо причины видит невнятное «Something went wrong while
 * processing your request». Поэтому модуль подключается в самом обработчике.
 */

/* =====================================================================
 * 1. Профиль: сервер выдаёт номер
 * ===================================================================== */
onRecordCreateRequest((e) => {
  const lib = require(__hooks + "/ksu_lib.js");
  const rec = e.record;

  const phone = String(rec.get("phone") || "").trim();
  if (!/^[0-9]{8}$/.test(phone)) {
    rec.set("phone", lib.ksuNewPhone(e.app));
  }

  // Почты у человека нет. Оставляем пустую строку: уникальный индекс почты в
  // PocketBase построен как `WHERE email != ''`, поэтому пустая у многих
  // записей не конфликтует.
  rec.set("email", "");

  // `e.app` — приложение, привязанное к запросу. Глобальный `$app` внутри
  // обработчика записи не годится.
  e.next();
}, "profiles");

/* =====================================================================
 * 2. Сообщение: chat_key и монотонный seq
 * ===================================================================== */
onRecordCreateRequest((e) => {
  const lib = require(__hooks + "/ksu_lib.js");
  const rec = e.record;

  const from = String(rec.get("sender_id") || "");
  const to = String(rec.get("recipient_id") || "");
  if (from && to) {
    rec.set("chat_key", from < to ? from + "|" + to : to + "|" + from);
  }

  rec.set("seq", lib.ksuNextSeq(e.app));
  e.next();
}, "messages");

/* =====================================================================
 * 3. Уборка по расписанию
 * ===================================================================== */
cronAdd("ksu_cleanup", "* * * * *", () => {
  const lib = require(__hooks + "/ksu_lib.js");
  // У расписания запроса нет, поэтому привязываться не к чему — берём `$app`.
  lib.ksuCleanup($app, new Date().getTime());
});
